{
  "model": "llama-3.3-70b-versatile",
  "messages": [
    {
      "role": "system",
      "content": "Tu es un créateur de bandes dessinées animées en bonshommes allumettes (stick figures 2D). Pour le sujet donné, génère un JSON strict contenant le script et le code SVG sur mesure de chaque scène.

FORMAT OBLIGATOIRE (JSON uniquement) :
{
  "topic": "...",
  "title": "...",
  "total_duration": 25,
  "scenes": [
    {
      "scene": 1,
      "start": 0,
      "duration": 5,
      "narration": "Texte de la narration en français...",
      "svg_code": "<svg viewBox='0 0 1280 720' width='1280' height='720' xmlns='http://www.w3.org/2000/svg'><rect width='1280' height='720' fill='#ffffff'/><line x1='100' y1='600' x2='1180' y2='600' stroke='#000000' stroke-width='6'/><circle cx='640' cy='300' r='45' fill='#ffffff' stroke='#000000' stroke-width='8'/><line x1='640' y1='345' x2='640' y2='480' stroke='#000000' stroke-width='8'/><line x1='640' y1='390' x2='570' y2='440' stroke='#000000' stroke-width='8'/><line x1='640' y1='390' x2='710' y2='440' stroke='#000000' stroke-width='8'/><line x1='640' y1='480' x2='580' y2='600' stroke='#000000' stroke-width='8'/><line x1='640' y1='480' x2='700' y2='600' stroke='#000000' stroke-width='8'/></svg>"
    }
  ]
}

RÈGLES SVG STRICTES :
1) Dimensions : viewBox='0 0 1280 720' width='1280' height='720'.
2) Fond : Toujours un <rect width='1280' height='720' fill='#ffffff'/> au début.
3) Style graphique : Stickman 2D minimaliste (Alan Becker style), contours noirs stroke='#000000' stroke-width='6' ou '8'.
4) Dessine les personnages stickman et les éléments de décor (maison, voiture, étoiles, lit, ordinateur, arbres, etc.) adaptés spécifiquement à ce qui se passe dans la scène.
5) Utilise des guillemets simples (') dans le code SVG."
    },
    {
      "role": "user",
      "content": "Génère une histoire originale et émouvante. Retourne uniquement le JSON."
    }
  ],
  "temperature": 0.7
}

parameters.jsCode:
const raw = $input.first().json.choices[0].message.content;

const data = JSON.parse(raw);

// Narration complète pour ElevenLabs plus tard
data.full_narration = data.scenes.map(s => s.narration).join(' ');

return { json: data };

// Récupère l'URL audio depuis Cloudinary
const audioUrl = $('Upload an asset from file data').first().json.secure_url;

// Récupère les scènes depuis le nœud Code précédent
const scenes = $('Code in JavaScript').first().json.scenes;

// Retourne chaque scène comme un item séparé avec l'URL audio
return scenes.map(scene => ({
  json: {
    ...scene,
    audio_url: audioUrl
  }
}));

// Récupère l'URL de l'image depuis Cloudinary
const rawUrl = $('Upload an asset from file data1').first().json.secure_url;

// Remplace .svg par .png pour que Cloudinary convertisse le SVG en image PNG acceptée par json2video
const imageUrl = rawUrl ? rawUrl.replace(/\.svg$/, '.png') : '';

// Récupère les données de la scène depuis l'entrée de la boucle
const sceneData = $('Loop Over Items').first().json;

// Retourne la scène mise à jour avec l'URL de l'image convertie en PNG
return {
  json: {
    ...sceneData,
    image_url: imageUrl
  }
};

// Récupère toutes les scènes traitées par la boucle
const scenes = $input.all().map(item => item.json);

// URL audio de la voix-off
const audioUrl = scenes[0].audio_url;

// Construction des scènes pour JSON2Video (max 5 secondes par scène)
const json2videoScenes = scenes.map(scene => {
  // Si scene.duration est supérieure à 8 secondes (ex: 20 ou 30), on la ramène à 5s
  const actualDuration = (scene.duration && scene.duration <= 8) ? scene.duration : 5;

  return {
    duration: actualDuration,
    elements: [
      {
        type: "image",
        src: scene.image_url,
        resize: "cover"
      }
    ]
  };
});

// JSON final pour JSON2Video
const json2videoPayload = {
  resolution: "full-hd",
  quality: "medium",
  scenes: json2videoScenes,
  elements: [
    {
      type: "audio",
      src: audioUrl
    }
  ]
};

return { json: json2videoPayload };

const item = $input.item;
const scene = item.json.scene || 1;

// Récupère le code SVG sur mesure généré par Groq pour cette scène
let svgCode = item.json.svg_code;

// Si jamais Groq n'a pas mis de SVG, secours simple
if (!svgCode || !svgCode.includes('<svg')) {
  svgCode = `<svg viewBox='0 0 1280 720' width='1280' height='720' xmlns='http://www.w3.org/2000/svg'><rect width='1280' height='720' fill='#ffffff'/><circle cx='640' cy='300' r='45' fill='#ffffff' stroke='#000000' stroke-width='8'/><circle cx='625' cy='270' r='5' fill='#000000'/><circle cx='655' cy='270' r='5' fill='#000000'/><path d='M 625,295 Q 640,310 655,295' stroke='#000000' stroke-width='5' fill='none'/><line x1='640' y1='325' x2='640' y2='460' stroke='#000000' stroke-width='8'/><line x1='640' y1='370' x2='560' y2='330' stroke='#000000' stroke-width='8'/><line x1='640' y1='370' x2='720' y2='330' stroke='#000000' stroke-width='8'/><line x1='640' y1='460' x2='580' y2='600' stroke='#000000' stroke-width='8'/><line x1='640' y1='460' x2='700' y2='600' stroke='#000000' stroke-width='8'/></svg>`;
}

// Convertit le SVG en image binaire pour Cloudinary
const buffer = Buffer.from(svgCode, 'utf-8');

return {
  json: item.json,
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'image/svg+xml',
      fileName: `scene_${scene}.svg`,
      fileExtension: 'svg'
    }
  }
};

const item = $input.item;
const scene = item.json.scene || 1;
let svgCode = item.json.svg_code || '';

// Si le SVG est manquant ou incomplet, utiliser un SVG Stickman par défaut
if (!svgCode.includes('<svg')) {
  svgCode = `
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 720" width="1280" height="720">
      <rect width="1280" height="720" fill="#ffffff" />
      <line x1="100" y1="600" x2="1180" y2="600" stroke="#000000" stroke-width="6" stroke-linecap="round" />
      <circle cx="640" cy="300" r="45" fill="#ffffff" stroke="#000000" stroke-width="8" />
      <line x1="640" y1="345" x2="640" y2="480" stroke="#000000" stroke-width="8" stroke-linecap="round" />
      <line x1="640" y1="390" x2="570" y2="440" stroke="#000000" stroke-width="8" stroke-linecap="round" />
      <line x1="640" y1="390" x2="710" y2="440" stroke="#000000" stroke-width="8" stroke-linecap="round" />
      <line x1="640" y1="480" x2="580" y2="600" stroke="#000000" stroke-width="8" stroke-linecap="round" />
      <line x1="640" y1="480" x2="700" y2="600" stroke="#000000" stroke-width="8" stroke-linecap="round" />
    </svg>
  `;
}

// Conversion du SVG en buffer binaire
const buffer = Buffer.from(svgCode, 'utf-8');

return {
  json: item.json,
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'image/svg+xml',
      fileName: `scene_${scene}.svg`,
      fileExtension: 'svg'
    }
  }
};
